WFJ.Data.add("gossip", {
  ["e40565df345adfb2"] = { "%s mette gli occhi su {name}!", "." },
  ["e4084da31c508aad"] = { "Prendi 'a lama così, poi lancia. Basta un colpo di polso, amico, una giravolta e il pranzo è servito.", "." },
  ["e40c002b16ad5035"] = { "Il ⟦The Butcher=Macellaio⟧ parlava del 'sangue degli innocenti' e del suo oscuro padrone, 'Kirtonos'. Di come dovesse placare il suo padrone.\n\nAlla fine, la bestia finì i suoi esperimenti. Eravamo stati prosciugati di ogni vita. I nostri spiriti, in frantumi. Il dolce abbraccio della morte era su di noi e lo accogliemmo a braccia aperte. Ma nella sua infinita crudeltà, il ⟦The Butcher=Macellaio⟧ ci strappò alla soglia della morte.\n\nDovevamo essere tenuti in vita e gettati in pasto ai suoi ghoul famelici. Rideva mentre guardava quei mostri divorare la nostra carne.", "." },
  ["e41a46135e61a034"] = { "Salutate i miei piccoli amici!", "." },
  ["e41a5a71e8ef7f75"] = { "I mortali sono...", "." },
  ["e41bd8fa8e9b1dee"] = { "I Guardiani della Notte da soli non possono proteggerci per sempre. Ci serve il sostegno dell'esercito di ⟦Stormwind=Roccavento⟧.", "." },
  ["e41d85b8004acb58"] = { "Non preoccuparti, ti troverò una bella casa.", "." },
  ["e42075d78e5bd587"] = { "Qualcosa non va nel gran signore. Fa' qualcosa!", "." },
  ["e435ee5d43176b00"] = { "%s inizia il conto alla rovescia.", "." },
  ["e440eb18a233c820"] = { "Salute, cittadin<o/a>. Sei venut<o/a> a dare una mano a mantenere la sicurezza di ⟦Southshore=Riva del Sud⟧?", "." },
  ["e447ceb36a00054e"] = { "Mio figlio saprebbe progettare una vettura più veloce di quel goffo rottame goblin!", "." },
  ["e44886f9f676177d"] = { "Il cancello è in vista! Ce la faremo! Ma prima devo riprendere fiato.", "." },
  ["e44ef0ae88fb7579"] = { "Cosa succede quando i Terrigeni si destabilizzano?", "." },
  ["e454cb1ea7b3e4eb"] = { "Mi sto preparando a risalire la cresta, {name}. Mi farebbe comodo un aiuto... vuoi venire con me?", "." },
  ["e461be3415be40f2"] = { "Per ⟦Darrowshire=Borgo di Darrow⟧!", "." },
  ["e46379f649dc27e5"] = { "La lama lenta penetra lo scudo.", "." },
  ["e46d7d31b321e2ce"] = { "Eseguito alla perfezione! Ora proseguiamo con la tua formazione...", "." },
  ["e46f086de2c74f85"] = { "Cerchi Grol'dar e il Darkfire Enclave? Li trovi nella caverna sotterranea chiamata Cleft of Shadow. Ci sono due gallerie che scendono in quella grotta, una appena a sud della Valle della Saggezza e l'altra da The Drag.", "." },
  ["e471c2f084a0eb26"] = { "Be', fin qui ce l'hai fatta... va' da Lavinia Crowe, vicino all'altra libreria. Se non combini guai con lei, forse potrai imparare qualcos'altro.", "." },
  ["e471ce74c22f6efc"] = { "Gli ordini sono dati! Avanti, mostriamogli di che pasta siamo fatti!", "." },
  ["e473545394e713a5"] = { "Ooh, che forza! Buona Veglia delle Ombre, {name}!", "." },
  ["e4798e1703e40794"] = { "Nella parte settentrionale di ⟦Darkshore=Rivafosca⟧ scorre il ⟦Cliffspring River=Fiume Altafonte⟧, che scende dalle terre ora note come ⟦Felwood=Vilbosco⟧. Dove il fiume sfocia nella ⟦Mist's Edge=Costa Bruma⟧, viaggia verso nord fin dove cominciano le parti più profonde dell'oceano. Una formazione rocciosa che alcuni chiamano Stone Claw, per la sua forma, è il luogo dove potresti trovare ciò che cerchi.\n\nTi avverto: i thresher si radunano presso lo Stone Claw e attaccano chiunque sconfini nel loro territorio.", "." },
  ["e47c04305d1d5bd4"] = { "È inquietante. Ti prego, continua.", "." },
  ["e4907b9e67a5bff0"] = { "Mille anni fa, gli elfi immortali, i semidei della foresta e i draghi combatterono contro la Legione sulle pendici dell'Hyjal.", "." },
  ["e49184095fcf93a2"] = { "Fuori di qui!", "." },
  ["e49b51c497734584"] = { "Ho trovato qualcosa... credo.", "." },
  ["e49f406f3987be8f"] = { "Ah! Ora la tua morte è certa!", "." },
  ["e4a1ce5d33c58100"] = { "Non voglio sentire storie, {name}. No, non c'è verso che tu possa entrare nella ⟦Searing Gorge=Gorgia Rovente⟧. Impossibile. Non succederà. Quante volte te lo devo dire? Non posso farti entrare! Non parli la lingua comune? Sei un orco travestito? N-O. NO!\n\nSe faccio entrare te, poi devo far entrare tutti. In men che non si dica vorranno entrare i tuoi amici più stretti, poi i loro parenti lontani, poi i loro amici, e così via. L'ultima volta che è successo... beh, dell'ultima volta non parliamone.", "." },
  ["e4a1eb4fe6440f26"] = { "Non sei all'altezza degli orchi ⟦Blackrock=Roccianera⟧!", "." },
  ["e4aed2a87b05a5e0"] = { "In qualità di coordinatore facente funzione di questo complesso, il mio dovere è assicurarmi che ogni forma di affari, lavoro, riposo e svago che possa svolgersi qui comporti un certo livello di noia.\n\nSe trovi che qualcosa che ti viene chiesto di fare sia troppo facile e privo di seccature, fammelo sapere immediatamente.", "." },
  ["e4b44a89fd5a37cb"] = { "{name}! Come te la passi, <ragazzo/ragazza>? Fammi vedere cos'hai imparato dall'ultima volta che ti ho visto, così vediamo se c'è qualcosa di nuovo che posso insegnarti.", "." },
  ["e4c3dff503470c1f"] = { "Cosa vuoi, Komak?", "." },
  ["e4cac66fe2607298"] = { "Morte e gloria al Re dei Lich!", "." },
  ["e4cdf7a0d15a9d87"] = { "Ma che... cosa sono quelle cose che strisciano verso di noi? Ci... ci attaccano!", "." },
  ["e4d3aa59a9d66f17"] = { "Pare che le ultime merci raccolte partiranno per ⟦Silithus=Silitus⟧ nei prossimi $2113w giorni. Una volta fatto, qualcuno dovrà venire a suonare il gong sull'Altare dello Scarabeo, fuori da ⟦Ahn'Qiraj=Ahn'qiraj⟧, per aprire i cancelli. È allora che le nostre bende torneranno utili.", "." },
  ["e4da5a4f70122547"] = { "<Padrone/Padrona> {name}! Il maestro Kang ha chiesto di te! Forse è giunto il tuo momento!", "." },
  ["e4ea055c699a1cab"] = { "L'esercito degli elfi della notte fu respinto attraverso Un'Goro, fino ai confini del deserto di Tanaris. Qualcosa a Un'Goro impedì ai Qiraji di conquistare quella terra. Non capisco bene questa parola, ma credo significhi 'Terre degli Dei'. Si dice che non riuscirono a 'prendere le Terre degli Dei'.", "." },
  ["e4f4703685067cdf"] = { "I Sons of Thaurissan ti guarderanno perire nel Ring of the Law!", "." },
  ["e4f56b429ab4759f"] = { "Oggi incontrerai i tuoi antenati!", "." },
})
